static inline float prefNet(const float *f) {
    float s = 0;
    for (int j = 0; j < NPH; j++) {
        float h = PFB1[j];
        for (int k = 0; k < NPF; k++) h += PFW1[j][k] * f[k];
        if (h > 0) s += PFW2[j] * h;
    }
    return s;
}
